dtsPropsFor.Card:
/** One bead on the Board (BoardCard from @overseer/shared). `state` drives the status chip; labels `overseer:abandoned` / `overseer:closed` / `overseer:verified` change it too. */
card: {
  bead: { id: string; title: string; description: string; status: 'open' | 'in_progress' | 'blocked' | 'closed' | 'deferred'; priority: number; labels: string[]; notes: string; assignee: string | null; closed_at: string | null; dependency_count: number };
  repo_id: string;
  batch_id: string | null;
  column: 'ready' | 'blocked' | 'running' | 'verifying' | 'review' | 'done';
  state: 'running' | 'settling' | 'verifying' | 'review' | 'verify_failed' | 'blocked' | 'idle' | 'landed_unclosed' | 'done' | 'reviewing' | 'awaiting_decision';
  harness: 'claude' | 'codex' | 'opencode' | null;
  branch: string | null;
  cost: number | null;
  elapsed_ms: number | null;
  session_status: 'running' | 'ended' | 'failed' | null;
  session_id: string | null;
  verify_failure: string | null;
  verify_block: 'none' | 'label' | 'output';
  tier: 'chore' | 'standard' | 'hard' | 'critic' | 'critic-chore' | null;
  model: string | null;
  account?: string | null;
  account_name: string | null;
  account_label: string | null;
  findings: { file: string | null; summary: string; severity: 'must' | 'should' }[] | null;
  accepted_note: string | null;
  pending_action?: { job_id: string; action: string; started_at: string } | null;
};
/** Draws the accent outline of the card whose pane is open. */
selected: boolean;
/** Opens the card; the card is a role=button div (Enter and Space activate it). */
onClick: () => void;

dtsPropsFor.BatchRow:
/** One batch (BatchSummary from @overseer/shared). `status` sets the chip and row tint; progress is (beads_done + beads_closed) / beads_total. */
batch: {
  id: string;
  origin_chat_id?: number | null;
  repo_id: string;
  title: string;
  branch: string;
  base_branch: string;
  status: 'open' | 'review' | 'merged' | 'abandoned';
  note: string | null;
  history: string | null;
  mr_url: string | null;
  conflict_files: string[] | null;
  created_at: string;
  updated_at: string;
  merged_at: string | null;
  merged_commit: string | null;
  setup_at: string | null;
  /** Set while in review behind an overlapping batch: the chip reads "waiting". */
  waiting_on: string | null;
  overlap_files: string[] | null;
  linked_chat_ids: number[];
  beads_total: number;
  beads_done: number;
  beads_closed: number;
  cost: number;
  /** Sessions with no reported cost: the cost reads as a floor ("≥ $x"). */
  cost_unknown: number;
  pending_action?: { job_id: string; action: string; started_at: string } | null;
};
onClick: () => void;

dtsPropsFor.Activity:
/** Board cards; only those with column 'running' are drawn, longest-running first, three rows then "and N more running". Same shape as Card's `card`. */
cards: { bead: { id: string; title: string; labels: string[] }; column: 'ready' | 'blocked' | 'running' | 'verifying' | 'review' | 'done'; state: string; elapsed_ms: number | null; cost: number | null }[];
/** Shows a muted "refreshing…" note while a newer board is on its way. */
refreshing?: boolean;

dtsPropsFor.PlainText:
/** Markdown-ish text: fences, bold and heading markers are stripped, `inline code` becomes <code>. */
text: string;
/** Render GitHub-style pipe tables as a scrollable <table> (Review's notes use this). */
tables?: boolean;

dtsPropsFor.Loading:
/** While true, `placeholder` is measured and painted as a shimmer; false renders `children`. */
loading: boolean;
/** Announced to assistive technology while loading. Default "Loading…". */
label?: string;
/** The arrived content's shape with placeholder values; required whenever `children` can render empty. */
placeholder?: React.ReactNode;
children: React.ReactNode;
templateProps?: Record<string, unknown>;

dtsPropsFor.Mascot:
state: 'idle' | 'thinking' | 'working' | 'asking' | 'sleeping' | 'offline' | 'error';
/** Low energy adds a sweat drop and heavy eyelids. Default 'normal'. */
energy?: 'high' | 'normal' | 'low';
/** Pixel size of the square SVG. Default 96; the rail uses 64 (32 on phones). */
size?: number;
/** Accessible name. Default "<state> mascot". */
label?: string;

dtsPropsFor.Rail:
/** Registered repositories; each is a chip with its cost. null while loading. */
repos: { id: string; path: string; base_branch: string; verify_command: string | null; setup_command: string | null; merge_mode: 'local-merge' | 'gitlab-mr'; batch_approver: 'user' | 'orchestrator'; worker_limit: number; review_rounds: number; verify_suspect?: number | null }[] | null;
/** Orchestrator status; drives the mascot, context percentage and "last active" lines. */
status: { bd_ok: boolean; orchestrator: { status: 'running' | 'ended' | 'failed' | 'idle'; native_session_id: string | null; last_activity_at: string | null; busy: boolean; model: string | null; context: { tokens: number; window: number } | null } } | null;
/** `restart_needed: true` shows the "Restart needed" badge. */
daemon?: { pid: number; started_at: string; commit: string | null; source_head: string | null; restart_needed: boolean } | null;
/** Per-repo cost totals; null shimmers the cost in each repo chip. */
costs: { repos: { repo_id: string; total: number; today: number; unknown: number }[]; batches: { batch_id: string; total: number; unknown: number }[] } | null;
/** Badge counts on the view buttons; `failed` adds a warning dot to Board. */
counts: { running: number; questions: number; failed: number; review: number };
/** The active view button. */
view: 'board' | 'office' | 'chat' | 'review' | 'setup' | 'plan' | 'usage' | 'discussions';
onView: (v: 'board' | 'office' | 'chat' | 'review' | 'setup' | 'plan' | 'usage' | 'discussions', target?: { section: 'daemon' }) => void;
onRepo: (id: string) => void;
/** Adds a warning dot to Setup. */
setupAlert: boolean;
onNewSession: () => void;
/** The orchestrator's current turn; a non-idle state shows an elapsed mm:ss beside the mascot. */
activity?: { state: 'thinking' | 'tool' | 'idle'; tool: string | null; summary: string | null; started_at: string } | null;
/** An unanswered question puts the mascot in its asking pose. */
pendingQuestion?: boolean;
/** Daemon unreachable: the mascot unplugs and the status lines hide. */
offline?: boolean;
loadFailed?: (paths: string[]) => boolean;

dtsPropsFor.UsageChart:
/** One stacked bar per day, segments per model; series[i] takes colour var(--chart-(i+1)), a sixth-plus series is "Other". `max` is the tallest day's total. */
stacks: { series: string[]; days: { day: string; total: number; segments: { key: string; value: number; codex: boolean }[] }[]; max: number };
/** Axis and tooltip format: dollars for 'reported' / 'estimated', k/M tokens for 'tokens'. */
measure: 'reported' | 'estimated' | 'tokens';
/** Accessible name of the chart SVG. */
label: string;

dtsPropsFor.AttachmentPicker:
/** The picker's state: `window.Overseer.useAttachments()` inside the component that owns the list. Its `addFiles(files)` stages images (png/jpeg/webp/gif, 8 MB, at most 4). */
state: { attachments: { file: File; url: string }[]; hint: string | null; addFiles: (files: Iterable<File>) => void; remove: (a: { file: File; url: string }) => void; clear: () => void; dropProps: object; pasteProps: object; toBody: () => Promise<{ name: string; mime: string; data: string }[]> };
disabled?: boolean;
/** Show the rejection hint ("x is not a supported image") after the button. */
showHint?: boolean;
